            legend[0],
            [[grid[r][start + c] == source_color for c in range(n)]
             for r in range(n)]
        )
        starts.append(start)

    out = [[0] * (n * n) for _ in range(n * n)]

    # Each lower panel encodes placements on the same n-by-n tile canvas.
    for start in starts:
        for i in range(n):
