            if row >= h:
                continue
            for j in range(n):
                color = grid[row][start + j]
                if color not in motifs:
                    continue
                out_color, shape = motifs[color]
                for a in range(n):
                    for b in range(n):
                        if shape[a][b]:
                            out[i * n + a][j * n + b] = out_color

    return out
